    constructor(C _c) { c = _c; }

    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        uint minDeposit = c.MinDeposit();
        uint beforeBalance = c.balances(address(this));
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        try c.Deposit{value: depositAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = c.balances(address(this));
        uint afterContractBalance = address(c).balance;

        if (depositAmount >= minDeposit) {
            assert(!reverted && afterBalance == beforeBalance + depositAmount && afterContractBalance == beforeContractBalance + depositAmount);
        } else {
            assert(reverted && afterBalance == beforeBalance && afterContractBalance == beforeContractBalance);
        }
    }

    receive() external payable {}
}

