contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint amount) public payable {
        require(depositAmount >= 1 ether, "setup deposit must be at least MinDeposit");
        require(address(this).balance >= depositAmount, "not enough balance for deposit");

        c.Deposit{value: depositAmount}();

        uint balBefore = c.balances(address(this));

        bool reverted;
        try c.CashOut(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));

        if (amount <= balBefore) {
            assert(!reverted && balAfter == balBefore - amount);
        } else {
            assert(reverted && balAfter == balBefore);
        }
    }

    receive() external payable {}
}

