        c.Deposit{value: depositAmount}();

        uint beforeCallerBalance = c.balances(address(this));
        uint beforeContractEth = address(c).balance;

        // The deciding call must be top-level and is not nested inside a try.
        c.CashOut(withdrawAmount);

        uint afterCallerBalance = c.balances(address(this));
        uint afterContractEth = address(c).balance;

        // General rule: a completed CashOut preserves the caller's total resources
        // (stored balance plus receiver balance) and reduces the contract's ETH by exactly the withdrawal.
        assert(
            afterCallerBalance + address(this).balance == beforeCallerBalance + beforeContractEth
            && beforeContractEth == afterContractEth + withdrawAmount
        );
    }

