        require(address(this).balance >= depositAmount, "not enough balance for deposit");

        // Make a qualifying deposit so the test contract has an observable stored balance.
        c.Deposit{value: depositAmount}();

        // Only attempt a withdrawal we can actually make, and require the contract
        // has enough Ether reserve to honor it (otherwise CashOut can revert on transfer).
        require(withdrawAmount <= c.balances(address(this)), "withdrawal exceeds stored balance");
        require(withdrawAmount <= address(c).balance, "contract lacks reserve for withdrawal");

        c.CashOut(withdrawAmount);

        // General invariant guaranteed by the Ether-transfer logic: after a successful
        // CashOut the caller's stored balance cannot exceed the contract's remaining
        // Ether reserve.  If CashOut ever paid out more than it subtracted, or let the
        // stored balance outgrow the reserve, this would break.
        assert(c.balances(address(this)) <= address(c).balance);
    }

    receive() external payable {}
}

