contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint minDeposit = c.MinDeposit();
        uint beforeBal = c.balances(address(this));

        bool reverted;
        try c.Deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = c.balances(address(this));

        if (amount < minDeposit) {
            assert(reverted && afterBal == beforeBal);
        } else {
            assert(!reverted && afterBal == beforeBal + amount);
        }
    }

    receive() external payable {}
}
